sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float beat;
uniform float beatTime;
uniform float beatIndex;
uniform float strength;
uniform float decay;
uniform float beats;
uniform float offset;
uniform float bpm;
uniform shader blurred;
uniform float threshold;
uniform float blur;
layout(color) uniform half4 color;
half4 main(float2 xy) {
    half4 c = image.eval(xy);
    half4 b = blurred.eval(xy);
    float a = max(float(b.a), 0.0001);
    float lift = smoothstep(threshold, 1.0, dot(float3(b.rgb), float3(0.2126, 0.7152, 0.0722)) / a);
    half3 g = b.rgb * half(lift * strength * beat) * color.rgb * color.a;
    half alpha = max(c.a, half(clamp(max(max(g.r, g.g), g.b), 0.0, 1.0)));
    return half4(min(c.rgb + g, half3(alpha)), alpha);
}
